import { computed, type Ref } from 'vue'
import { usePagination } from './usePagination'
import { STATUS_META } from '@/dashboard/constants/status'
import { formatDayLabel } from '@/dashboard/utils/date'
import {
  collectMilestoneEvents,
  findMilestone,
  findMilestoneIn,
  milestoneDate,
  MILESTONE_SIDES,
  SIDE_LABELS,
  type MilestoneSide,
} from '@/dashboard/utils/milestones'
import { classifyTask, isTaskComplete } from '@/dashboard/utils/projectStatus'
import type { ProjectBaseline, ProjectDetail, ProjectTask } from './useProjectMilestones'

/** Placeholder for values 3DEXPERIENCE does not provide. */
export const NOT_AVAILABLE = '-'

export interface EventColumn {
  key: string
  label: string
  /** Event this column belongs to (e.g. "PP0"); grouped columns share a header. */
  group?: string
  /** Indo or Customer milestone shown in this column (live data only). */
  side?: MilestoneSide
  /** First column of a group, or of the event block: draws a divider on its left. */
  groupStart?: boolean
}

/** Second header row: an event group spanning its columns, or a standalone column. */
export interface EventHeaderGroup {
  key: string
  label: string
  span: number
  /** Set for a standalone (ungrouped) column, which spans both lower header rows. */
  column?: EventColumn
}

export interface EventRow {
  key: string
  index: number
  location: string
  model: string
  name: string
  /** Project image URL ('' when the project has none) */
  imageUrl: string
  customer: string
  volDay: string
  pl: string
  /** Cell text per EventColumn.key; a second line ("\n") is shown as a note. */
  cells: Record<string, string>
  /** Baseline dates per milestone EventColumn.key, latest baseline first */
  baselineCells: Record<string, BaselineDate[]>
  remarks: string
  currentStatus: string
  /** Display status, e.g. "Delayed" */
  status: string
}

/** A milestone's date in one project baseline, shown small under the current date. */
export interface BaselineDate {
  /** Short label, e.g. "BL 2" */
  label: string
  /** e.g. "11 Aug '26" */
  date: string
  /** Full baseline title, for the tooltip */
  title: string
}

/** "BL <n>": the number at the end of the baseline title, else its creation order (1 = oldest). */
function baselineLabel(baseline: ProjectBaseline, index: number, count: number): string {
  const number = /(\d+)\s*$/.exec(baseline.title)?.[1] ?? String(count - index)
  return `BL ${number}`
}

/**
 * The milestone's date in each baseline (latest first). Baselines without the milestone,
 * or whose date equals the project's current date (same day), are skipped.
 */
function baselineDates(
  project: ProjectDetail,
  event: string,
  side: MilestoneSide,
  current: ProjectTask | undefined,
): BaselineDate[] {
  const currentDate = current ? milestoneDate(current) : null
  const currentLabel = currentDate ? formatDayLabel(currentDate) : ''
  const dates: BaselineDate[] = []
  project.baselines.forEach((baseline, i) => {
    const task = findMilestoneIn(baseline.milestones, event, side)
    const date = task ? milestoneDate(task) : null
    if (!date) return
    const label = formatDayLabel(date)
    if (label === currentLabel) return
    dates.push({
      label: baselineLabel(baseline, i, project.baselines.length),
      date: label,
      title: baseline.title,
    })
  })
  return dates
}

/** "CustomerQAV" project attribute (details API); NOT_AVAILABLE when empty. */
const QAV_COLUMN: EventColumn = { key: 'customerQAV', label: 'Customer QAV' }

/** "11 Aug '26" plus a note line for completed / late milestones. */
function milestoneCellText(task: ProjectTask): string {
  const date = milestoneDate(task)
  const dateText = date ? formatDayLabel(date) : NOT_AVAILABLE

  if (isTaskComplete(task)) return `${dateText}\nCompleted`
  return classifyTask(task) === 'delayed' ? `${dateText}\nLate` : dateText
}

const cellKey = (event: string, side: MilestoneSide) => `milestone:${event}:${side}`

/** Events across all projects (first-seen sequence order), each with Indo + Customer columns. */
function buildColumns(projects: ProjectDetail[]): EventColumn[] {
  const events = collectMilestoneEvents(projects)
  const columns: EventColumn[] = events.flatMap((event) =>
    MILESTONE_SIDES.map((side, sideIdx) => ({
      key: cellKey(event, side),
      label: SIDE_LABELS[side],
      group: event,
      side,
      groupStart: sideIdx === 0,
    })),
  )
  return [...columns, { ...QAV_COLUMN, groupStart: true }]
}

function buildRow(project: ProjectDetail, index: number, columns: EventColumn[]): EventRow {
  const cells: Record<string, string> = {}
  const baselineCells: Record<string, BaselineDate[]> = {}
  for (const column of columns) cells[column.key] = NOT_AVAILABLE

  for (const column of columns) {
    if (!column.group || !column.side) continue
    const milestone = findMilestone(project, column.group, column.side)
    if (milestone) cells[column.key] = milestoneCellText(milestone)
    baselineCells[column.key] = baselineDates(project, column.group, column.side, milestone)
  }
  cells[QAV_COLUMN.key] = project.attributes.customerQav || NOT_AVAILABLE

  return {
    key: project.projectId,
    index,
    // Custom project attributes; "-" when the project does not have a value.
    location: project.attributes.location || NOT_AVAILABLE,
    // One Physical Product attachment title (revisions share it); "-" when there is none.
    model: project.attributes.physicalProducts[0] || NOT_AVAILABLE,
    name: project.projectLabel,
    imageUrl: project.attributes.imageUrl,
    customer: NOT_AVAILABLE,
    volDay: project.attributes.volDay || NOT_AVAILABLE,
    pl: project.attributes.pl || NOT_AVAILABLE,
    cells,
    baselineCells,
    remarks: project.attributes.description || NOT_AVAILABLE,
    currentStatus: NOT_AVAILABLE,
    status: STATUS_META[project.statusKey].label,
  }
}

/** Groups consecutive columns of the same event under one header cell. */
function buildHeaderGroups(columns: EventColumn[]): EventHeaderGroup[] {
  const groups: EventHeaderGroup[] = []
  for (const column of columns) {
    const last = groups[groups.length - 1]
    if (column.group && last && !last.column && last.label === column.group) {
      last.span++
    } else if (column.group) {
      groups.push({ key: `group:${column.group}`, label: column.group, span: 1 })
    } else {
      groups.push({ key: column.key, label: column.label, span: 1, column })
    }
  }
  return groups
}

/**
 * Event Status table model: one row per project, Indo/Customer columns per event.
 * Paginated here so only the rows of the visible page are built (rows are costly:
 * every event column looks up the milestone and its baseline dates).
 */
export function useEventStatus(projects: Ref<ProjectDetail[]>, pageSize: number) {
  const columns = computed(() => buildColumns(projects.value))
  const pagination = usePagination(projects, pageSize)
  const pageRows = computed(() => {
    const first = pagination.rangeStart.value
    return pagination.pageItems.value.map((project, i) => buildRow(project, first + i, columns.value))
  })

  const hasGroups = computed(() => columns.value.some((column) => column.group))
  const headerGroups = computed(() => buildHeaderGroups(columns.value))

  return { columns, pageRows, hasGroups, headerGroups, pagination }
}
