/**
 * Project name filter, controlled from the widget preferences (3DDashboard ▸ widget ▸ Edit):
 *
 *   - "Filter projects by name" (boolean) — off: show every Project Space; on: show only
 *     projects whose name starts with one of the prefixes below.
 *   - "Project name prefixes" (text) — comma-separated, case-insensitive.
 *
 * Preferences are read on every load, so a change applies on the next refresh, which the
 * dashboard triggers automatically when the preferences are saved.
 */

export const PREF_FILTER_ENABLED = 'project_name_filter'
export const PREF_FILTER_PREFIXES = 'project_name_prefixes'

export const DEFAULT_PREFIXES = ['STAND COMP', 'HANDLE BAR', 'MUFFLER ASSY EXH']

/* eslint-disable no-unused-vars -- parameter names in function types */
interface WidgetLike {
  getValue?: (name: string) => unknown
  addPreference?: (pref: Record<string, unknown>) => void
  addEvent?: (event: string, callback: () => void) => void
}
/* eslint-enable no-unused-vars */

const getWidget = (): WidgetLike | undefined =>
  (window as unknown as { widget?: WidgetLike }).widget

/** Registers both preferences. Call once at start-up, after the Credentials preference. */
export function registerProjectFilterPreferences(widget: WidgetLike) {
  widget.addPreference?.({
    name: PREF_FILTER_ENABLED,
    type: 'boolean',
    label: 'Filter projects by name',
    defaultValue: 'false',
  })
  widget.addPreference?.({
    name: PREF_FILTER_PREFIXES,
    type: 'text',
    label: 'Project name prefixes (comma-separated)',
    defaultValue: DEFAULT_PREFIXES.join(', '),
  })
}

/**
 * Upper-cased prefixes to keep, or an empty list when the filter is off (show all).
 * UWA stores boolean preferences as the strings "true" / "false".
 */
export function activeNamePrefixes(): string[] {
  try {
    const widget = getWidget()
    const enabled = String(widget?.getValue?.(PREF_FILTER_ENABLED) ?? 'false').toLowerCase() === 'true'
    if (!enabled) return []
    const raw = widget?.getValue?.(PREF_FILTER_PREFIXES)
    const text = typeof raw === 'string' ? raw : DEFAULT_PREFIXES.join(',')
    return text
      .split(',')
      .map((p) => p.trim().toUpperCase())
      .filter(Boolean)
  } catch {
    return []
  }
}

/** True when the name passes the given prefix list (an empty list passes everything). */
export function matchesNamePrefixes(name: string, prefixes: readonly string[]): boolean {
  if (!prefixes.length) return true
  const upper = name.trim().toUpperCase()
  return prefixes.some((prefix) => upper.startsWith(prefix))
}

/** Calls `callback` when the user saves the widget preferences or uses the widget's Refresh. */
export function onWidgetPreferencesChanged(callback: () => void) {
  const widget = getWidget()
  widget?.addEvent?.('endEdit', callback)
  widget?.addEvent?.('onRefresh', callback)
}
